/**
 * Node resolve hook that points a content import at its French twin.
 *
 * The search index is generated by tsx, outside Vite, so the build's module-swapping
 * plugin never runs. The generator therefore read the English content whichever language
 * was being built, and the French site shipped an English index: French readers searched
 * and got English titles and English snippets back.
 *
 * This does the same swap the Vite plugin does, for the generator: with DLG_LOCALE=fr an
 * import of "../src/lib/x" resolves to "../src/lib/x.fr.ts" when that twin exists. With
 * the variable unset it does nothing at all, so the English build is untouched.
 *
 * Registering it has to happen before the generator's own imports resolve, which is why
 * the generator is reached through a wrapper rather than being called directly.
 */

import { existsSync } from "node:fs";
import { fileURLToPath } from "node:url";

const LIB_MODULE = /^(file:\/\/.*\/src\/lib\/.+?)(\.fr)?\.(ts|tsx)$/;

export async function resolve(specifier, context, next) {
  const resolved = await next(specifier, context);
  if (process.env.DLG_LOCALE !== "fr") return resolved;

  const m = LIB_MODULE.exec(resolved.url);
  if (!m || m[2]) return resolved;

  const twin = `${m[1]}.fr.${m[3]}`;
  if (!existsSync(fileURLToPath(twin))) return resolved;

  return { ...resolved, url: twin, shortCircuit: true };
}
